    /// <summary>
    /// Update Filename and subject in SrsReportRunMailer object
    /// </summary>
    /// <param name = "_kpmgSRSReportRunMailer">Type SrsReportRunMailer</param>
    private void kpmgUpdateSrsReportRunMailerForPurchaseOrderFoodLiqHwe(SrsReportRunMailer    _kpmgSRSReportRunMailer)
    {
        PurchTable                          kpmgPurchTable;
        //METPlannerCodeSetup                 METPlannerCodeSetup;
        Map                                 metPOEmailSubjectMap, metPOEmailContentMap;
        METPurchTable                       METPurchTable;
        VendPurchOrderJour                  kpmgVendPurchOrderJourStd;
        str                                 kpmgVersionNum, kpmgPOStatus, kpmgDocNum;
        Filename                            kpmgFileName        = _kpmgSRSReportRunMailer.parmKPMGFileName();
        SysEmailSubject                     kpmgEmailSubject    = _kpmgSRSReportRunMailer.parmKPMGSysEmailSubject();
        SysEmailContents                    kpmgEmailContents   = _kpmgSRSReportRunMailer.parmKPMGSysEmailContents();
        SrsReportDataContract               kpmgContract        = reportContract;

        if(kpmgContract && kpmgContract.parmRdpContract() as PurchPurchaseOrderContract)
        {
            PurchPurchaseOrderContract kpmgPurchConfirmContract  = kpmgContract.parmRdpContract() as PurchPurchaseOrderContract;
            
            kpmgVendPurchOrderJourStd   = VendPurchOrderJour::findRecId(kpmgPurchConfirmContract.parmRecordId());
            kpmgPurchTable              = kpmgVendPurchOrderJourStd.purchTable();
            
            kpmgDocNum      = kpmgVendPurchOrderJourStd.PurchOrderDocNum;
            kpmgVersionNum  = subStr(kpmgDocNum, strFind(kpmgDocNum, metConstants::hyphen, 1, strLen(kpmgDocNum))+1, strLen(kpmgDocNum));

            metPOEmailSubjectMap = new Map(Types::String, Types::String);
            metPOEmailSubjectMap.insert(METConstants::PONumber, kpmgVendPurchOrderJourStd.PurchId);
            metPOEmailSubjectMap.insert(METConstants::POVersionNumber, kpmgVersionNum);
            if(kpmgFileName)
            {
                _kpmgSRSReportRunMailer.parmKPMGFileName(SysEmailMessage::stringExpand(kpmgFileName, metPOEmailSubjectMap));
            }

            if(kpmgPurchTable.PurchStatus == PurchStatus::Canceled)
            {
                kpmgPOStatus = metConstants::Cancelled;
            }
            else if(str2Num(kpmgVersionNum) == 1)
            {
                kpmgPOStatus = metConstants::Created;
            }
            else
            {
                kpmgPOStatus = metConstants::Amended;
            }
            metPOEmailSubjectMap.insert(METConstants::POStatus, kpmgPOStatus);
            metPOEmailSubjectMap.insert(METConstants::WarehouseName, InventLocation::find(kpmgPurchTable.InventLocationId).Name);
            if(kpmgEmailSubject)
            {                
                _kpmgSRSReportRunMailer.parmKPMGSysEmailSubject(SysEmailMessage::stringExpand(kpmgEmailSubject, metPOEmailSubjectMap));
            }

            metPOEmailContentMap = new Map(Types::String, Types::String);
            metPOEmailContentMap.insert(METConstants::PONumber, kpmgVendPurchOrderJourStd.PurchId);
            metPOEmailContentMap.insert(METConstants::POStatus, kpmgPOStatus);
            metPOEmailContentMap.insert(METConstants::POCurrency, kpmgPurchTable.CurrencyCode);
            metPOEmailContentMap.insert(METConstants::POAmount, strFmt("@SYS82282",kpmgVendPurchOrderJourStd.Amount));

            // Task 90134: CB220 - Planner Codes - Check/Update Build
            // TODO Commenting for now, will have to be updated with buyer group logic
            /*
            select firstonly PlannerCodePersonnelNumber from METPlannerCodeSetup
                    exists join METPurchTable
