                    && METPurchTable.PurchId == kpmgPurchTable.PurchId;
            if(METPlannerCodeSetup.PlannerCodePersonnelNumber)
            {
                metPOEmailContentMap.insert(METConstants::PlannerName, HcmWorker::worker2Name(METPlannerCodeSetup.PlannerCodePersonnelNumber));
            }*/

            if(kpmgEmailContents)
            {   
                _kpmgSRSReportRunMailer.parmKPMGSysEmailContents(SysEmailMessage::stringExpand(kpmgEmailContents, SysEmailTable::htmlEncodeParameters(metPOEmailContentMap)));
            }
